    let raw = match crate::es_tokenizer::tokenize(source) {
        Ok(trees) => trees,
        Err(error) => {
            return json!({"path":path,"contentId":content_identifier,"bytes":source.len(),"declarations":[],"exports":[],"imports":[],"initialization":[],
