fn dependency(path: &str, specifier: &str) -> Option<String> {
    if !specifier.starts_with('.') || specifier.contains('\\') {
        return None;
    }
    let mut parts: Vec<_> = path.split('/').collect();
    parts.pop();
    for part in specifier.split('/') {
        match part {
            "" | "." => {}
            ".." => {
                parts.pop()?;
